package com.prasanth.vitalguard.service;import com.prasanth.vitalguard.model.VitalReading;import com.prasanth.vitalguard.repository.VitalRepository;import org.springframework.stereotype.Service;import java.util.List;
@Service public class VitalService{private final VitalRepository repo;private final RuleEngine engine;public VitalService(VitalRepository repo,RuleEngine engine){this.repo=repo;this.engine=engine;}public VitalReading create(VitalReading v){engine.evaluate(v);return repo.save(v);}public List<VitalReading> all(){return repo.findAll();}public List<VitalReading> alerts(){return repo.findAll().stream().filter(v->!"NORMAL".equals(v.getRiskLevel())).toList();}}
